// #af074d (17b180ffa7055a7916af074d) — заблокированный пользователь / пользователь заблокированного бизнеса видит
// отдельный экран «הכניסה לחשבון חסומה» (Figma 721:1083) без формы входа: блок «צוות התמיכה», «פנייה לתמיכה», «חזרה לכניסה».
// spec: specs/auth-login.md (раздел 7) · seed: tests/seed.spec.ts (гость).
// Экран берёт причину из адреса /login?notice=blocked&reason=… — тот же экран (data-testid=account-blocked), что после
// реального отказа входа (проверено 04.11: вход паролем в заблокированный QA-EMPTY-0411 — тот же экран; это ручной шаг).
// Только просмотр гостем → @prod-safe. 390 — в десктопном прогоне с шириной окна 390 (телефоны в проекте — только кандидат).
import { test, expect, Page } from '@playwright/test';

const BLOCKED_TITLE = 'הכניסה לחשבון חסומה';
const BLOCKED_BODY = 'החשבון שלכם או החשבון של העסק חסום כרגע, ולכן לא ניתן להיכנס. צוות התמיכה יוכל לבדוק מה קרה ולעזור לכם להמשיך.';
const SUPPORT_RESPONSE = 'נבדוק את סטטוס החשבון ונחזור אליכם במייל, בדרך כלל תוך יום עסקים אחד.';
const SUPPORT_EMAIL = 'simulator@shnaider.pro';
const SUPPORT_NOTE = 'עובדים בעסק שחשבונו פעיל? אפשר לפנות גם למנהל החשבון אצלכם.';
const MAILTO = /^mailto:simulator@shnaider\.pro/;

async function openScreen(page: Page, reason: string) {
  await page.goto(`/login?notice=blocked&reason=${reason}`);
  const screen = page.getByTestId('account-blocked');
  await expect(screen).toBeVisible();
  await expect(screen).toHaveAttribute('data-reason', reason);
  return screen;
}

/** AC1: экран без формы входа — нет полей, «כניסה», «שכחתי סיסמה»; одна кнопка «פנייה לתמיכה» (нижняя ссылка панели скрыта). */
async function expectNoForm(page: Page) {
  await expect(page.getByRole('textbox')).toHaveCount(0);
  await expect(page.getByLabel('סיסמה')).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'כניסה', exact: true })).toHaveCount(0);
  await expect(page.getByRole('link', { name: 'שכחתי סיסמה' })).toHaveCount(0);
  await expect(page.getByRole('link', { name: 'פנייה לתמיכה' })).toHaveCount(1);
  await expect(page.getByRole('button', { name: 'התנתקות' })).toHaveCount(0);
}

/** AC2: блок «צוות התמיכה» (время ответа, адрес, строка про менеджера), mailto, «חזרה לכניסה». */
async function expectSupport(page: Page, withNote: boolean) {
  const support = page.getByTestId('blocked-support');
  await expect(support).toContainText('צוות התמיכה');
  await expect(support).toContainText(SUPPORT_RESPONSE);
  await expect(support).toContainText(SUPPORT_EMAIL);
  if (withNote) await expect(support).toContainText(SUPPORT_NOTE);
  else await expect(support).not.toContainText(SUPPORT_NOTE);
  await expect(page.getByRole('link', { name: 'פנייה לתמיכה' })).toHaveAttribute('href', MAILTO);
  await expect(page.getByRole('button', { name: 'חזרה לכניסה' })).toBeVisible();
}

test.describe('Вход — экран «הכניסה לחשבון חסומה» без формы (#af074d · #17b180ffa7055a7916af074d)', () => {
  for (const reason of ['user', 'business']) {
    test(`гость: reason=${reason} → отдельный экран «${BLOCKED_TITLE}» без полей, «צוות התמיכה», mailto ${SUPPORT_EMAIL}; «חזרה לכניסה» → форма @desktop @prod-safe #af074d #17b180ffa7055a7916af074d`, async ({ page }) => {
      const screen = await openScreen(page, reason);
      // AC1 + комментарий программиста: заблокированный пользователь и пользователь заблокированного бизнеса — один текст кадра 721:1134.
      await expect(page.getByRole('heading', { level: 1, name: BLOCKED_TITLE })).toBeVisible();
      await expect(screen).toContainText(BLOCKED_BODY);
      await expectNoForm(page);
      await expectSupport(page, true);

      // «חזרה לכניסה» возвращает форму входа.
      await page.getByRole('button', { name: 'חזרה לכניסה' }).click();
      await expect(page.getByTestId('account-blocked')).toHaveCount(0);
      await expect(page.getByRole('heading', { level: 1, name: 'כניסה לחשבון' })).toBeVisible();
      await expect(page.getByLabel('מייל')).toBeVisible();
      await expect(page.getByLabel('סיסמה')).toBeVisible();
      await expect(page.getByRole('button', { name: 'כניסה', exact: true })).toBeVisible();
      // Комментарий программиста: ?notice=blocked снимается с адреса.
      expect.soft(new URL(page.url()).searchParams.get('notice'), 'notice в адресе после «חזרה לכניסה»').toBeNull();
    });
  }

  test('гость: reason=removed — та же раскладка с «הגישה לעסק הוסרה», без формы, строка про менеджера есть @desktop @prod-safe #af074d #17b180ffa7055a7916af074d #922c63', async ({ page }) => {
    const screen = await openScreen(page, 'removed');
    await expect(page.getByRole('heading', { level: 1, name: 'הגישה לעסק הוסרה' })).toBeVisible();
    await expect(screen).not.toContainText(BLOCKED_TITLE);
    await expectNoForm(page);
    await expectSupport(page, true);
  });

  test('гость: reason=deleted — та же раскладка с «החשבון העסקי נמחק», без формы и без строки про менеджера @desktop @prod-safe #af074d #17b180ffa7055a7916af074d #92bd0e', async ({ page }) => {
    const screen = await openScreen(page, 'deleted');
    await expect(page.getByRole('heading', { level: 1, name: 'החשבון העסקי נמחק' })).toBeVisible();
    await expect(screen).not.toContainText(BLOCKED_TITLE);
    await expectNoForm(page);
    // У удалённого бизнеса нет менеджера, к которому можно обратиться (комментарий программиста).
    await expectSupport(page, false);
  });

  test('гость, ширина 390: reason=user и reason=business — экран без формы, блок поддержки и кнопки видны, без горизонтальной прокрутки @desktop @prod-safe #af074d #17b180ffa7055a7916af074d', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    for (const reason of ['user', 'business']) {
      await openScreen(page, reason);
      await expect(page.getByRole('heading', { level: 1, name: BLOCKED_TITLE })).toBeVisible();
      await expectNoForm(page);
      await expectSupport(page, true);
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
      expect(overflow, `reason=${reason}: горизонтальная прокрутка на 390`).toBeLessThanOrEqual(1);
      for (const el of [page.getByTestId('blocked-support'), page.getByRole('link', { name: 'פנייה לתמיכה' }), page.getByRole('button', { name: 'חזרה לכניסה' })]) {
        const box = await el.boundingBox();
        expect(box, `reason=${reason}: элемент не отрисован`).not.toBeNull();
        expect(box!.x).toBeGreaterThanOrEqual(0);
        expect(box!.x + box!.width).toBeLessThanOrEqual(391);
      }
    }
  });
});
